// 只有显式新目录才能写独立接待段，旧Office换人从不暗开本profile或补历史岗位。
#include "political_office_reception_profile.hpp"
#include "resident/domains/politics/succession/political_succession_profile.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
namespace hanmo::resident {
bool is_political_office_reception_fact_kind(const StableId& k){return k=="political_office_reception_assumed";}
Outcome<Integer> political_office_reception_selected_version(const std::vector<std::pair<StableId,StableId>>& modules){Integer count=0;for(const auto& m:modules)if(m.first==political_office_reception_domain){if(m.second!="1"||++count!=1)return {false,0,common_failure("PoliticalOfficeReceptionModuleMismatch").error};}if(!count)return {true,0,{}};auto original=political_succession_selected_version(modules);if(!original.ok)return original;if(original.value!=1)return {false,0,common_failure("PoliticalOfficeReceptionOriginalProfileRequired").error};return {true,1,{}};}
// 原首职目录显式提供Office/座所，不能由仅有一个角色名构造新公权。
Outcome<std::optional<PoliticalOfficeReceptionCatalog>> decode_political_office_reception_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){const auto* dynamic=scenario.find("dynamic_world");const auto* group=dynamic?dynamic->find(political_office_reception_domain):nullptr;if(!group)return {true,std::nullopt,{}};if(std::find(caps.begin(),caps.end(),"political_office_receptions_v1")==caps.end())return {false,{},common_failure("PoliticalOfficeReceptionCapabilityRequired").error};auto original=decode_political_succession_profile(scenario,caps);if(!original.ok)return {false,{},original.error};if(!original.value)return {false,{},common_failure("PoliticalOfficeReceptionOriginalProfileRequired").error};auto decoded=decode_political_office_reception_catalog(*group);if(!decoded.ok)return {false,{},decoded.error};if(decoded.value.policies.empty()||decoded.value.policies.size()>4096)return {false,{},common_failure("InvalidPoliticalOfficeReceptionCatalog").error};return {true,std::move(decoded.value),{}};}
Status validate_political_office_reception_layout(const CommonStore& common,const std::vector<std::pair<StableId,StableId>>& modules,const PoliticalOfficeReceptionState* state){auto selected=political_office_reception_selected_version(modules);if(!selected.ok)return {false,{},selected.error};if(bool(state)!=(selected.value==1)||(state&&state->version!=1))return common_failure("PoliticalOfficeReceptionProfileMismatch");if(!state){for(const auto& row:common.state().facts.rows())if(is_political_office_reception_fact_kind(row.second.kind)||row.second.domain==political_office_reception_domain)return common_failure("PoliticalOfficeReceptionProfileRequired",row.first);for(const auto& h:common.state().history)if(is_political_office_reception_command(h.kind))return common_failure("PoliticalOfficeReceptionProfileRequired",h.result_id);for(const auto& row:common.state().results.rows())if(row.second&&is_political_office_reception_command(row.second->kind))return common_failure("PoliticalOfficeReceptionProfileRequired",row.first);}return common_success();}
// JSON额外payload仍拒绝，只有真实本表恰一记录可注册为Common头。
Status validate_political_office_reception_fact_header(const CommonStore& common,const PoliticalOfficeReceptionState& s,const FactRecord& h){const auto* row=s.assignments.find(h.id);return s.version==1&&row&&row->id==h.id&&h.domain==political_office_reception_domain&&is_political_office_reception_fact_kind(h.kind)&&political_office_reception_fact_sequence(common,h.id)?common_success():common_failure("PoliticalOfficeReceptionFactMismatch",h.id);}
// 岗位认领不产生Office变更或任命ID，只能回唯一实际本业务fact。
bool valid_political_office_reception_effect(const StableId& kind,const PoliticsEffects& e){return is_political_office_reception_command(kind)&&e.appointment_id.empty()&&e.receipt_ids.empty()&&e.fact_ids.size()==1&&organization_instance_sequence(e.fact_ids.front(),"political_office_reception").has_value();}
}
